t = int(input())
for i in range(t):
	(n, k) = map(int, input().split())
	s = str(input())
	s = list(['0'] * k + list(s) + ['0'] * k)
	c = 0
	for j in range(k, k + n):
		if s[j] == '1' and s[j - k] == '0' and (s[j + k] == '0'):
			c += 1
			if j + k < k + n:
				s[j + k] = '1'
	print(c)
